package main

import (
	"bufio"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"os"
	"path/filepath"

	"github.com/alecthomas/gometalinter"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run parser.go <source_file> <struct_name>")
		os.Exit(1)
	}

	sourceFile := os.Args[1]
	structName := os.Args[2]

	// Parse the Go source code into an AST
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, sourceFile, nil, parser.ParseComments)
	if err != nil {
		fmt.Printf("Error parsing %s: %v\n", sourceFile, err)
		return
	}

	// Find the struct definition
	for _, decl := range file.Decls {
		switch d := decl.(type) {
		case *ast.GenDecl:
			if d.Tok == token.TYPE && strings.Contains(d.Specs[0].Type.Name.String(), structName+" ") {
				ast.Inspect(file, func(n ast.Node) bool {
					if n.(*ast.StructType).Name.Name == structName {
						return true
					}
					return false
				})
			}
		}
	}

	// Write the generated Avro schema to a file
	schemaPath := filepath.Join(filepath.Dir(sourceFile), fmt.Sprintf("%s.avsc", structName))
	out, err := ioutil.ReadFile(schemaPath)
	if err != nil {
		fmt.Printf("Error reading existing schema file %s: %v\n", schemaPath, err)
	} else if !strings.HasSuffix(string(out), "\n") {
		fmt.Println("Schema already exists.")
		return
	}

	err = ioutil.WriteFile(schemaPath, []byte(""), 0644)
	if err != nil {
		fmt.Printf("Error writing schema file %s: %v\n", schemaPath, err)
		return
	}

	fmt.Println("Avro schema written successfully to:", schemaPath)
}

func checkSchemaErrors(err error) {
	if err != nil {
		panic(fmt.Errorf("failed to create schema: %w", err))
	}
}
```

### How to Use the Program:

1. **Save the Code**: Save the above code into a file called `parser.go`.

2. **Run the Program**: Execute the following command in your terminal:

   ```sh
   go run parser.go src/main.go MyStruct
   ```

   Replace `src/main.go` with the path to your Go source file and `MyStruct` with the name of the struct you want to convert.

3. **Output**: The program will output an Avro schema file (e.g., `MyStruct.avsc`) containing the definitions of the fields in the struct.

This program uses the `gometalinter` tool to help ensure that the struct is correctly typed according to the Go language standards before attempting to generate the Avro schema.

